var LA_LIGA_DECK = LA_LIGA_RAW_CARDS.map((c) => {
  const nameParts = c.name.trim().split(" ");
  const firstName = nameParts.length > 1 ? nameParts[0] : "";
  const lastName = nameParts.length > 1 ? nameParts.slice(1).join(" ") : c.name;
  return {
    id: c.id,
    name: c.name,
    displayName: c.displayName,
    firstName,
    lastName,
    season: c.season,
    position: c.position,
    positions: [c.position],
    ovr: c.ovr,
    club: c.club,
    clubCode: c.clubCode,
    clubAbbreviation: c.clubCode,
    league: c.league,
    tags: c.tags,
    imagePath: c.imagePath,
    imageUrl: c.imagePath,
    crestPath: c.crestPath,
    clubCrestUrl: c.crestPath,
    auctionBasePrice: c.basePrice,
    basePrice: c.basePrice,
    nation: "LA LIGA ICON",
    eraStats: {
      appearances: 38,
      goals: c.position === "ATK" ? Math.round(c.ovr / 3.4) : c.position === "MID" ? Math.round(c.ovr / 8) : 0,
      cleanSheets: c.position === "GK" ? Math.round(c.ovr / 4.8) : c.position === "DEF" ? Math.round(c.ovr / 5.2) : void 0,
      trophies: c.tags
    }
  };
});

